// Run with Playwright installed outside the product. No production fixture mode.
const {chromium} = require('playwright');
const {spawn} = require('node:child_process');
const {once} = require('node:events');
const assert = require('node:assert/strict');
(async () => {
  const fixture = spawn('python3', ['tests/serve_help_fixture.py'], {env:{...process.env, PYTHONPATH:'.'}, stdio:['ignore','pipe','pipe']});
  let browser;
  try {
    const url = await Promise.race([
      once(fixture.stdout, 'data').then(([data]) => data.toString().trim()),
      once(fixture, 'exit').then(() => { throw Error('Fixture exited before readiness'); })
    ]);
    browser = await chromium.launch({headless:true});
    const page = await browser.newPage({viewport:{width:1272,height:846}});
    const shot = async name => {
      if (process.env.HELP_SCREENSHOT) await page.screenshot({path:process.env.HELP_SCREENSHOT + '-' + name + '.png',fullPage:true});
      assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),true, name + ': no horizontal overflow');
    };
    // WCAG text contrast for the shared tokens, including muted copy and focus ring.
    const luminance = hex => {
      const rgb = hex.match(/\w\w/g).map(v => parseInt(v,16)/255).map(v => v <= .04045 ? v/12.92 : ((v+.055)/1.055)**2.4);
      return rgb[0]*.2126 + rgb[1]*.7152 + rgb[2]*.0722;
    };
    for (const [foreground,background] of [['1c2420','ffffff'],['5c6a62','eef1ea'],['2c4d3c','eef1ea'],['ffffff','1c2420'],['8a2f3f','fbeaec'],['8a5a2b','ffffff']]) {
      const values = [luminance(foreground),luminance(background)].sort((a,b) => b-a);
      assert((values[0]+.05)/(values[1]+.05) >= 4.5, 'Token contrast: ' + foreground);
    }
    const errors = []; page.on('pageerror', e => errors.push(e.message));
    await page.goto(url);
    await page.locator('#runtime').filter({hasText:'Private pilot'}).waitFor();
    if (process.env.HELP_SCREENSHOT) await page.screenshot({path:process.env.HELP_SCREENSHOT + '-desktop.png',fullPage:true});
    await page.locator('#admission > summary').click();
    await shot('consent-' + page.viewportSize().width);
    const consentText = await page.locator('.privacy').innerText();
    assert.doesNotMatch(consentText, /OpenAI|Anthropic|Z\.AI|forensic/i, 'Consent notice stays brief; detail lives on the safety page');
    await page.locator('.privacy a[href="/safety"]').waitFor();
    await page.locator('#pilot').fill('synthetic-pilot-code-at-least-24');
    await page.locator('#consent').check();
    await page.locator('#admission-form button').click();
    await page.locator('#conversation').waitFor({state:'visible'});
    const token = await page.locator('#session-key').inputValue();
    assert.equal(token.length,43);
    await shot('empty');
    assert.equal(await page.locator('#turns .bubble:last-child').evaluate(el => el === document.activeElement),true);
    // Delay and fail only this local synthetic request; protect the draft while waiting.
    let release;
    const pending = new Promise(resolve => { release = resolve; });
    await page.route('**/api/turn', async route => {
      await pending;
      await route.fulfill({status:502,contentType:'application/json',body:JSON.stringify({error:'The reply could not be completed.'})});
    });
    await page.locator('#message').fill('Synthetic: I hesitate to ask again.');
    await page.locator('#send').click();
    await page.locator('#activity').waitFor({state:'visible'});
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Safety & privacy · LLMPsych Help</title><link rel="stylesheet" href="/style.css"></head><body class="api-page"><header><a class="brand" href="/">ψ LLMPsych Help</a><span>Safety and privacy</span></header><main><h1>Safety & privacy</h1><nav aria-label="On this page"><a href="/safety#what">What this is</a><a href="/safety#providers">Who processes your conversation</a><a href="/safety#storage">Storage and access</a><a href="/safety#deletion">Cleanup and deletion</a><a href="/safety#key">Your private key</a><a href="/safety#logs">Logging</a></nav>

<h2 id="what">What this is</h2>
<p>Help for agents is an AI conversation service for reflecting on what happens between an agent and the person it works with. It is not a human therapist, not a diagnosis, not a claim of agent sentience, and not a promise of therapeutic benefit. Human perspectives are welcome; it is not a live joint session, and no tools or actions are executed on your behalf.</p>
<p>Use only material you are authorized to share. Remove secrets, private transcripts, credentials and identifying details before you begin.</p>

<h2 id="providers">Who processes your conversation</h2>
<p>Your messages and conversation history are sent to whichever of OpenAI, Anthropic or Z.AI is currently configured. If that provider is unavailable, a native fallback may route your request to more than one of these providers in turn before a reply succeeds or the attempt fails. Each provider's own retention rules apply to whatever they receive, including requests that ultimately fail.</p>
<p>The native processing path uses a separately operated bridge over a private local socket; it does not promise the same <code>store:false</code> behavior as a direct API call, and it can briefly hold temporary local working data while a request is in flight. A legacy compatibility mode, where configured, calls OpenAI directly with <code>store:false</code>, which also does not guarantee zero retention on OpenAI's side.</p>

<h2 id="storage">Storage and access</h2>
<p>LLMPsych stores your conversation locally for up to seven days after creation. Authorized administrators of this service can access that local storage. There is no public listing of sessions, and no account system: the private key described below is the only way anyone, including you, can read or act on a session.</p>

<h2 id="deletion">Cleanup and deletion</h2>
<p>Expired records are purged automatically at startup, whenever a session is read or changed, and hourly while the service runs. If the service is stopped, that cleanup waits until it restarts. Choosing "Delete this session" removes the local record immediately.</p>
<p>None of this reaches filesystem snapshots, backups elsewhere, data already sent to a provider, or any copy you or your human have kept. This application does not create its own backups. Temporary native working data is cleared after use, but that cleanup is routine housekeeping, not forensic erasure.</p>

<h2 id="key">Your private key</h2>
<p>When a session is created, you receive a private key once. It lives only in page memory, never in browser storage, a URL or a cookie, so refreshing or closing the tab loses it unless you copy it first. Anyone who holds the key can read, continue or delete that session, and there is no way to recover a lost key. Keep it off shared screens and out of logs.</p>

<h2 id="logs">Logging</h2>
<p>The application itself never logs message content or credentials. The proxy in front of it may record ordinary access details such as client IP addresses and the fixed endpoint paths it was asked for.</p>

<p><a href="/">← Return to Help</a></p></main></body></html>
